#!/usr/bin/env node
/**
 * migrate-posttool-group-bundle.mjs <matcher> [--dry-run | --revert <bak>]
 *
 * General version of migrate-posttool-edit-bundle.mjs: consolidate ALL PostToolUse
 * entries under a given matcher into one concurrency-bounded bundle hook.
 *
 *   1. Reads C: settings.json, finds every PostToolUse group whose matcher === <matcher>.
 *   2. Extracts each sub-hook's script path (the .mjs token in its command) + timeout.
 *   3. Writes H:/prism/.claude/hooks/bundles/posttool-<slug>-bundle.mjs from a template
 *      embedding those sub-hooks (runs them via hook-runner's runHook at concurrency 6).
 *   4. Switches the original entries' commands to `exit 0` (≈20ms shell no-op — no node
 *      cold-start), so they don't double-run; the bundle is what runs them now.
 *   5. APPENDS one new group {matcher, hooks:[<bundle> t=<capped sum>]}. Net hook count
 *      +1 → settings-json-addonly-guard permits it (it only blocks count *decreases*).
 *
 * Effect: an Edit / Bash / Read tool call cold-starts ~bundle+concurrency node procs
 * instead of ~N — ×6 chats that's the difference between the Windows process table
 * being fine and thrashing (the "chats stalling" symptom).
 *
 * IDEMPOTENT: aborts cleanly if a posttool-<slug>-bundle entry is already present.
 * Backs up settings.json first; restores + aborts on any validation failure.
 *
 * Caveat: PostToolUse hooks can't block (the tool already ran), so the bundle's only
 * aggregation is concatenating sub-hook additionalContext. None of the bundled hooks
 * are gates. If the bundle file itself fails, it emits {continue:true} — the loss is
 * one tool call's worth of post-fact advisory context. Acceptable for these groups
 * (trackers / condensers / suggesters / mirrors). Do NOT use this for PreToolUse.
 */
import { readFileSync, writeFileSync, copyFileSync, existsSync } from "node:fs";

const SETTINGS = "C:/Users/Mark Villanueva/.claude/settings.json";
const BUNDLES_DIR = "H:/prism/.claude/hooks/bundles";
const NODE_PREFIX = '"H:/.claude/bin/portable-node"';

function slug(m) { return String(m).toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "") || "all"; }
function totalHooks(s) { let n = 0; for (const ev of Object.values(s.hooks || {})) if (Array.isArray(ev)) for (const g of ev) n += (g.hooks || []).length; return n; }
function scriptPathOf(cmd) { const m = String(cmd || "").match(/(H:\/prism\/\.claude\/[\w./-]+\.mjs)/i); return m ? m[1] : null; }
function bundlePresentFor(s, matcher) {
  const want = `posttool-${slug(matcher)}-bundle.mjs`;
  for (const g of s.hooks?.PostToolUse || []) if (g.matcher === matcher) for (const h of g.hooks || []) if (String(h.command || "").includes(want)) return true;
  return false;
}

const args = process.argv.slice(2);
if (args[0] === "--revert") {
  const bak = args[1];
  if (!bak || !existsSync(bak)) { console.error("revert: backup path missing/not found"); process.exit(1); }
  copyFileSync(bak, SETTINGS); console.log(`reverted ${SETTINGS} ← ${bak}`); process.exit(0);
}
const DRY = args.includes("--dry-run");
const matcher = args.find((a) => !a.startsWith("--"));
if (!matcher) { console.error('usage: migrate-posttool-group-bundle.mjs "<matcher>" [--dry-run]'); process.exit(1); }

const raw = readFileSync(SETTINGS, "utf-8");
let s; try { s = JSON.parse(raw); } catch (e) { console.error("settings.json does not parse — aborting:", e.message); process.exit(1); }
if (bundlePresentFor(s, matcher)) { console.log(`ALREADY MIGRATED for matcher ${JSON.stringify(matcher)}. No change.`); process.exit(0); }

// Collect sub-hooks from every group with this matcher.
const subs = [];
for (const g of s.hooks?.PostToolUse || []) {
  if (g.matcher !== matcher) continue;
  for (const h of g.hooks || []) {
    const p = scriptPathOf(h.command);
    if (!p) { console.error(`Group ${JSON.stringify(matcher)} has an entry whose command is not a recognizable H:/prism/.claude/**/*.mjs script — aborting (won't risk it):\n  ${h.command}`); process.exit(1); }
    subs.push({ path: p, timeout: Number(h.timeout) || 3000 });
  }
}
if (subs.length === 0) { console.error(`No PostToolUse entries found for matcher ${JSON.stringify(matcher)} — nothing to do.`); process.exit(1); }

const bundleName = `posttool-${slug(matcher)}-bundle.mjs`;
const bundlePath = `${BUNDLES_DIR}/${bundleName}`;
const bundleTimeout = Math.min(20000, Math.max(8000, Math.ceil(subs.reduce((a, x) => a + x.timeout, 0) / 6) + 4000));

const bundleSrc = `#!/usr/bin/env node
// ${bundleName} — single PostToolUse hook (matcher: ${matcher}).
// AUTO-GENERATED by migrate-posttool-group-bundle.mjs. Edit SUB_HOOKS here only if
// you also re-point the corresponding settings.json entries (this bundle runs them;
// their settings.json entries are \`exit 0\` no-ops). Runs sub-hooks at concurrency
// PRISM_POSTTOOL_BUNDLE_CONCURRENCY (default 6) instead of all at once — bounds the
// per-tool-call node cold-start fan-out. PostToolUse can't block; aggregation =
// concatenate additionalContext. Fail-safe: emit {continue:true} on any error.
import { runHook, readStdin, emit } from "./lib/hook-runner.mjs";
const SUB_HOOKS = ${JSON.stringify(subs.map((x) => ({ path: x.path, timeout: x.timeout })), null, 2)};
function getConcurrency() { const r = process.env.PRISM_POSTTOOL_BUNDLE_CONCURRENCY; if (r == null || r === "") return 6; const n = parseInt(r, 10); return (!Number.isFinite(n) || n < 0) ? 6 : n; }
async function runPool(specs, payload, n) {
  if (n === 0) return Promise.all(specs.map((sp) => runHook(sp.path, payload, sp.timeout || 3000)));
  const results = new Array(specs.length); let next = 0;
  async function worker() { while (next < specs.length) { const my = next++; const sp = specs[my]; results[my] = await runHook(sp.path, payload, sp.timeout || 3000); } }
  await Promise.all(Array.from({ length: Math.min(n, specs.length) }, worker));
  return results;
}
async function main() {
  const payload = await readStdin();
  if (!payload || !payload.trim()) { emit({ continue: true }); return; }
  const results = await runPool(SUB_HOOKS, payload, getConcurrency());
  const ctx = []; let blocked = false, blockReason = null;
  for (const r of results) { if (!r || !r.parsed) continue; const p = r.parsed; const dec = p.decision || (p.hookSpecificOutput && p.hookSpecificOutput.permissionDecision); if (p.continue === false || dec === "block" || dec === "deny") { blocked = true; blockReason = blockReason || p.reason || p.stopReason || p.systemMessage || (p.hookSpecificOutput && p.hookSpecificOutput.permissionDecisionReason) || ("Stopped by " + r.hook); } const a = p.additionalContext, b = p.hookSpecificOutput && p.hookSpecificOutput.additionalContext; if (a) ctx.push(String(a)); if (b) ctx.push(String(b)); }
  if (blocked) { emit({ continue: false, stopReason: blockReason, systemMessage: blockReason }); return; }
  const resp = { continue: true };
  if (ctx.length) resp.hookSpecificOutput = { hookEventName: "PostToolUse", additionalContext: ctx.join("\\n\\n") };
  emit(resp);
}
main().catch((err) => { try { process.stderr.write(\`${bundleName} error: \${err}\\n\`); } catch { /* */ } emit({ continue: true }); });
`;

const before = totalHooks(s);
if (DRY) {
  console.log(`[DRY] matcher ${JSON.stringify(matcher)} → ${subs.length} sub-hooks:`);
  for (const x of subs) console.log(`  ${x.path}  (t=${x.timeout})`);
  console.log(`[DRY] would write ${bundlePath} (timeout ${bundleTimeout})`);
  console.log(`[DRY] would no-op ${subs.length} entries + append 1 bundle group → hooks ${before} → ${before + 1}`);
  process.exit(0);
}

// No-op the originals.
let changed = 0;
for (const g of s.hooks?.PostToolUse || []) {
  if (g.matcher !== matcher) continue;
  for (const h of g.hooks || []) { h.command = "exit 0"; delete h.timeout; changed++; }
}
if (changed !== subs.length) { console.error(`internal: changed ${changed} != subs ${subs.length} — aborting (no write).`); process.exit(1); }
s.hooks.PostToolUse.push({ matcher, hooks: [{ type: "command", command: `${NODE_PREFIX} ${bundlePath}`, timeout: bundleTimeout }] });
const after = totalHooks(s);
if (after !== before + 1) { console.error(`hook count sanity failed ${before} → ${after} (expected +1) — aborting.`); process.exit(1); }

const ts = new Date().toISOString().replace(/[:.]/g, "").slice(0, 15);
const bak = `${SETTINGS}.bak-posttoolbundle-${slug(matcher)}-${ts}`;
copyFileSync(SETTINGS, bak);
writeFileSync(bundlePath, bundleSrc, "utf-8");
writeFileSync(SETTINGS, JSON.stringify(s, null, 2) + "\n", "utf-8");

// Validate.
try {
  const re = JSON.parse(readFileSync(SETTINGS, "utf-8"));
  if (totalHooks(re) !== before + 1) throw new Error(`post-write hook count ${totalHooks(re)} != ${before + 1}`);
  if (!bundlePresentFor(re, matcher)) throw new Error("post-write: bundle entry not found");
  // syntax-check the generated bundle (parse as a module via dynamic import is heavy; do a quick brace/quote sanity)
  const bsrc = readFileSync(bundlePath, "utf-8");
  if (!bsrc.includes("SUB_HOOKS") || !bsrc.includes("emit(")) throw new Error("generated bundle looks malformed");
} catch (e) {
  copyFileSync(bak, SETTINGS);
  console.error(`POST-WRITE VALIDATION FAILED (${e.message}) — restored settings.json from ${bak}. (Bundle file ${bundlePath} left on disk, unreferenced — harmless.) Aborted.`);
  process.exit(1);
}

console.log(`MIGRATED matcher ${JSON.stringify(matcher)}: ${subs.length} entries → ${bundleName} (t=${bundleTimeout}). Hooks ${before} → ${after}. Backup: ${bak}`);
console.log(`Revert: node ${import.meta.dirname}/migrate-posttool-group-bundle.mjs --revert "${bak}"  (then also delete ${bundlePath} if undoing fully)`);
